                  {"Release notes"}
                </p>
                <p className="art:mt-1 art:text-muted-foreground art:text-sm">
                  {"Browse by area"}
                </p>
              </div>
              <div className="art:overflow-x-auto art:@min-[1024px]/artemis:overflow-visible">
                <ArtemisSegmentedTabs items={TAB_ITEMS} value={filter} onValueChange={choose} ariaLabel="Filter release notes" listClassName="art:inline-flex art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-1 art:min-w-max art:@min-[1024px]/artemis:w-full art:@min-[1024px]/artemis:min-w-0 art:@min-[1024px]/artemis:flex-col art:@min-[1024px]/artemis:items-stretch art:@min-[1024px]/artemis:bg-muted art:@min-[1024px]/artemis:p-0" buttonClassName="art:rounded-full art:min-h-10 art:gap-6 art:@min-[1024px]/artemis:w-full art:@min-[1024px]/artemis:justify-between art:@min-[1024px]/artemis:px-4"/>
              </div>
            </aside>
            <div className="art:min-w-0">
              <AnimatePresence mode="wait">
                <motion.section key={filter} className="art:space-y-3" aria-live="polite" initial={reduce ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={reduce ? { opacity: 0, transition: NO_MOTION } : { opacity: 0, y: -6, transition: LIST_SWAP }} transition={reduce ? NO_MOTION : switched ? LIST_SWAP : { ...ARTEMIS_SPRING_LAYOUT, delay: 0.43 }}>
                  {releases.map((release, index) => (<motion.article key={release.id} className="art:rounded-2xl art:border art:border-border/60 art:bg-background art:p-5 art:@min-[640px]/artemis:p-7" initial={switched && !reduce ? { opacity: 0, y: 14 } : false} animate={{ opacity: 1, y: 0 }} transition={reduce ? NO_MOTION : ARTEMIS_SPRING_LAYOUT}>
                      <div className="art:flex art:flex-wrap art:items-center art:gap-2 art:text-muted-foreground art:text-sm">
                        <span>
                          {release.date}
                        </span>
                        <span aria-hidden="true">
                          {"\u00B7"}
                        </span>
                        <span>
                          {release.category}
                        </span>
                        {filter === "all" && index === 0 ? (<span className="art:ml-auto art:inline-flex art:rounded-full art:bg-[linear-gradient(105deg,#f27777,#efc65b,#62c899,#58a9df,#f27777)] art:p-px">
                            <span className="art:rounded-full art:bg-background art:px-2.5 art:py-1 art:font-medium art:text-foreground art:text-xs">
                              {"Latest"}
                            </span>
                          </span>) : null}
