                      <h2 className="art:mt-4 art:max-w-2xl art:text-balance art:tracking-[-0.035em] art:text-4xl art:font-medium">
                        {release.title}
                      </h2>
                      <p className="art:mt-3 art:max-w-2xl art:text-pretty art:text-muted-foreground art:leading-7">
                        {release.summary}
                      </p>
                      <ul className="art:mt-6 art:grid art:gap-2 art:@min-[640px]/artemis:grid-cols-3">
                        {release.points.map((point) => (<li key={point} className="art:flex art:items-start art:gap-2.5 art:text-sm art:leading-6">
                            <span className="art:mt-1 art:grid art:size-5 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted">
                              <CheckIcon />
                            </span>
                            {point}
                          </li>))}
                      </ul>
                    </motion.article>))}
                </motion.section>
              </AnimatePresence>
              <section className="art:mt-5 art:flex art:flex-col art:items-start art:justify-between art:gap-6 art:rounded-2xl art:border art:border-border/60 art:bg-background art:p-6 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:items-center art:@min-[640px]/artemis:p-8">
                <div>
                  <p className="art:text-muted-foreground art:text-sm">
                    {"A calm monthly recap"}
                  </p>
                  <h2 className="art:mt-2 art:max-w-lg art:text-balance art:tracking-[-0.035em] art:text-4xl art:font-medium">
                    {"Get the changes worth knowing about."}
                  </h2>
                </div>
                <ArtemisButtonLink href="#" size="lg">
                  {"Subscribe"}
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-4" aria-hidden="true">
                    <path d="M5 12h14"/>
                    <path d="m12 5 7 7-7 7"/>
                  </svg>
                </ArtemisButtonLink>
              </section>
            </div>
          </div>
        </div>
      </main>
    </>);
}

